-- V7: настоящие расы Corise (7 рас) и их древа наследия (70 узлов).
-- Временные расы V3 заменяются: совпавшие по названию обновляются, остальные временные удаляются,
-- если на них ничего не ссылается. Узлы наследия добавляются только расам, у которых их ещё нет.

-- 1. Расы (во временную таблицу, чтобы сверять с ней при очистке)
CREATE TEMP TABLE seed_race (
    out_name      VARCHAR(100) NOT NULL,
    in_name       VARCHAR(100) NOT NULL,
    short_desc    TEXT         NOT NULL,
    appearance    TEXT         NOT NULL,
    lore          TEXT         NOT NULL,
    relationships TEXT         NOT NULL,
    status        VARCHAR(50)  NOT NULL,
    archetype     VARCHAR(50)  NOT NULL,
    lifespan      INT
) ON COMMIT DROP;

INSERT INTO seed_race (out_name, in_name, short_desc, appearance, lore, relationships, status, archetype, lifespan) VALUES

-- ---------------------------------------------------------------- Автоматоны
('Автоматоны', 'Конструкты',
$t$Наурские конструкты. Металлические гуманоидные конструкции, обычно без лица и с раскрывающимися пластинами на животе$t$,
$t$Автоматоны - это существа из металла и сложных механизмов. Эти конструкты при этом опасны. Их тело имеет плату на "животе", которая раскрывается в "пасть". Некоторые модели имеют на спине нечто, похожее на остатки ручного запитывания путем выработки энергии из физического воздействия. Ныне то место, где ранее был генератор Стирлинга, либо просто имеет странный круговой узор, либо вовсе отсутствует у новой линейки автоматонов. Обычно у них нет лица, но если ваш автоматон был произведен вне территории Общего разума РЕ9, то его создатель мог дать ему одно. На территории Общего разума автоматоны производятся для максимальной эффективности, и лица были бы тратой ресурсов производства.$t$,
$t$"Органики несовершенны. Автоматоны не лучше. Но, в отличие от органических форм жизни, наша эволюция подчинена нам"

Автоматоны - непризнанная раса, ныне представляющая угрозу всему Северному континенту, недавно разрушив одного из главных игроков Северного континента и своих создателей - Наурское королевство. Если ранее они были созданы для автоматизации ручного труда и замены армии для избегания потерь в случае войны, ныне они управляются иной силой, неким "Создателем". Сейчас они имеют одни из самых продвинутых технологий, самое удивительное из которых - массовый сборщик инса.

Продолжительность жизни неизвестна, но автоматонов новой модели стали производить около 13 лет назад.$t$,
$t$Тривианцы, что населяли северный остров вместе с наурами, готовятся к войне против бездушных, остальной мир с тревогой наблюдает за происходящим, конечно, реагируя на события лишь тогда, когда им "выгодно". Большинство видят в автоматонах лишь машин для убийства и боятся их.$t$,
'Непризнанные', 'Логика, Само-Эволюция, Модульность', NULL),

-- ------------------------------------------------------------------ Вампиры
('Вампиры', 'Шадонар',
$t$Бледные с острыми клыками и меткой на шее в форме клыка$t$,
$t$Шадонар во многом похожи на личей - они тоже мертвенно-бледны, но даже между ними есть отличия. Шадонар имеют куда более острые клыки, а также темное пятно в форме клыка на шее, похожее на татуировку. Их волосы обычно черные, иногда багровые, а глаза могут быть от розовых до черных. Также их легко можно отличить по их манере всегда одеваться роскошно, будто они всегда на вечернем балу. Конечно, если они не приключенцы.$t$,
$t$"Страх перед нашими клыками забавен... Куда опаснее наша речь, улыбка, жесты, мысли. Воевать и агрессивно атаковать - слишком грубо для разумных существ. Потому мы защищаем свои интересы иными путями."

Дети ночи и крови - так их прозвали. Обычно вампиры собираются в кланы, основанные на семейных узах. Раньше большинство вампиров собирались в более мелкие кланы, образуя небольшие и слабые королевства, где корона передавалась по уникальным для каждого клана правилам. С началом патульякской эры все больше и больше среди вампиров стала преобладать мода на сбор нескольких семей в республики, где несколько глав из разных семей управляют одним, более большим и мощным государством. Вампиры известны своим очарованием и опасностью. А также тем, что из них выходят отличные любовники или любовницы. Из-за анатомии, сильно отличающейся от "живых" рас, они не способны иметь детей от других рас, потому размножаются только среди "своих".$t$,
$t$Их репутация - странная и непонятная. Кто-то их боится, кто-то относится как к обычному представителю признанной расы. Они разбросаны по всему миру и весьма закрыты друг от друга. Семьи разделены и обычно крайне враждебны друг к другу, но держат агрессию меж собой холодной. С остальными расами они не имеют прямых конфликтов, которые бы распространялись на всех абсолютно. Но обычно вампиры более спокойны к личам из-за их схожей не живой природы.$t$,
'Признанные', 'Кровь, Очарование', 400),

-- ------------------------------------------------------------ Высшие эльфы
('Высшие эльфы', 'Патульякские Аэ’Ли',
$t$Высокие, стройные, необычный цвет волос и глаз, заостренные уши, бледная кожа$t$,
$t$Они высоки и стройны. Их кожа остается белой, жемчужной и совсем редко светло-серой. Волосы и глаза из-за их связи с магией этого мира могут быть любого цвета. У них длинные и заостренные уши, кончики которых лишь слегка скруглены.$t$,
$t$"Как дети магии и последователи отца Магии, мы обязаны показать остальным то, какие чудеса и идеи несет за собой Инс. То, чего мы сможем достичь, показав им силу и возможности цивилизации Отца"

Когда именно Высшие эльфы появились, неизвестно. Но прекрасно известны их цели и древние традиции. Они всеми силами стремятся показать через силу и мощь своей цивилизации возможности, которые дал этому миру Инс, Отец магии, их бог-покровитель. Большую часть истории они были прекрасными магами, развивая магические науки и понимая все больше о магической части мира. И недавно им почти получилось достичь этой цели. Как и у Виртувианцев, у Аэ’Ли был свой "Золотой век" 400 лет назад в Патульякской Эре. Она закончилась всего 15 лет назад развалом империи Патульяк и началом эпохи раздора. Распад империи заставил многих Патульяк подумать о том, к чему действительно им следует стремиться, чтобы получить благословление.$t$,
$t$Аэ’Ли ведут себя в целом, зачастую, весьма дружелюбно и снисходительно по отношению к другим расам. Но между ними и Тривианцами есть напряжение, которое пошло с начала патульякской эры. Ныне два народа мало контактируют. Также высшие эльфы имеют крайне негативные отношения с орками и напряженные отношения с другими непризнанными расами.$t$,
'Признанные', 'Магия, Просвещение', 200),

-- ------------------------------------------------------------------- Кицунэ
('Кицунэ', 'Каэлен''ари',
$t$Имеют уши и хвост различных окрасов. В некоторых случаях на руках, ногах может встречаться мех$t$,
$t$Внешний вид кицунэ сильно схож разнообразием и чертами с человеческим. Их кожа также может иметь множество различных оттенков, варьируясь от бледных тонов вплоть до темных в зависимости от их места обитания, но кроме цвета кожи также меняется окрас и наличие меха, а также ушей и хвоста, как и размер, форма последних.

Кицунэ не имеют человеческих ушей, вместо этого из их волос торчит пара лисьих ушей. Кроме того, что слух у них от этого лучше, они также могут показывать эмоции Каэлен'ари, даже когда последний не особо спешит их показывать.$t$,
$t$"Вечные скитания приносят лишь страдания. Пришло время нам забрать то, что наше по праву. Пора защитить наш новый дом"

Как и со многими расами, точно определить момент появления кицунэ в мире нельзя. Можно лишь сказать, что они появились где-то в тот же промежуток времени, что и другие расы. Каэлен'ари верят, что все они произошли от Рейнэ - богини огня, и что те из них, кто сохранил цвет волос и меха, наиболее близкий по окрасу к ней, красный, максимально близки к их божеству. Хотя по факту никто не замечал разницы между ними, но легенда сформировала свои эффекты на культуру кицунэ. "Красные" Каэлен'ари социально считаются выше остальных и уважаются соответственно.

Ранее государства кицунэ преимущественно располагались к югу от моря Бретфордж, но с формированием империи людей кицунэ медленно двигались на восток, позднее закрепившись в регионе между множеством притоков реки Редклиф, но и оттуда кицунэ медленно мигрировали в регион за великими горами на юг основного континента, основавшись между реками Каула и Восово, где теперь и располагается большинство кицунэ.$t$,
$t$Кицунэ рассматривают другие расы как чужаков, всегда доверяя больше "своим". К тому же они все так же помнят прошлые обиды на людей и эльфов, из-за которых кицунэ поколениями слонялись по континенту, пока не закрепились на его юго-восточном полуострове.$t$,
'Признанные', 'Ловкость, Хитрость, Братство', 70),

-- --------------------------------------------------------------------- Личи
('Личи', 'Асцендиане',
$t$Ходячие трупы. Могут менять облик на тот, что был "при жизни", но всегда с трупно-бледной кожей$t$,
$t$Асцендиане существуют в двух обликах, постоянно балансируя между маскировкой и своей истинной, пугающей природой.

"Истинный облик" - их физическое тело - это труп, который продолжает медленно разлагаться с течением времени. За каждый год, проведенный в не-жизни, их тело стареет на несколько дней, постепенно проходя все стадии разложения, пока в конечном итоге не останется лишь чистый скелет. Этот процесс, однако, противоестественен: их плоть не привлекает ни насекомых, ни падальщиков, будто сама природа боится прикоснуться к ней.

"Иллюзорный облик" - с помощью магии (обычно заклинание передается обращенному сразу после обращения или написано в гримуарах вместе с ритуалом обращения) асцендианин может скрыть свой истинный вид под иллюзией своего облика "при жизни". Однако эта маскировка несовершенна. Независимо от того, какой была их кожа раньше, в иллюзорной форме она всегда остается мертвенно-бледной, а от самого лича исходит едва уловимый холод - постоянное напоминание о его истинной сущности.$t$,
$t$"Вечность для всех относительна. Для одних она имеет границу, когда для нас она ограничена лишь волей нашей или смертью"

Как первые личи появились в мире, неизвестно. Но со временем они не менялись, будто застыли во времени. У асцендиан крайне мало государств, и те не могут похвастаться ни сильным дипломатическим влиянием в мире, ни единством. Традиционно личи верят в бога смерти, но есть одно государство, жители которого уверовали в мертвое божество времени. Малое число государств асцендиан объясняется кажущейся ненужностью служения обществу при своей вечной жизни. Но часто в глубинках и далеких от общества других рас местностях собираются культы личей. Часто те похищают путешественников, насильно отдавая их души тьме и обращая в такую же нежить.

Продолжительность жизни: личи живут, пока не решат умереть сами или пока их не убьют.$t$,
$t$В мире их боятся даже грозные Ур'Кха и защищающие свои колонии Мицелиды. Отношение к ним такое же, как и к членам непризнанных рас. Они - изгои среди "элиты" мира. Но на фоне угрозы автоматонов даже асцендиане кажутся не настолько плохими.$t$,
'Признанные', 'Противоречие, Тайна, Смерть', NULL),

-- -------------------------------------------------------------------- Люди
('Люди', 'Виртувианцы',
$t$Разнообразная внешность, не имеют внешних отличий$t$,
$t$Люди - одна из самых разнообразных рас. Их рост, телосложение, цвет кожи, волос и глаз могут варьироваться до бесконечности, отражая их происхождение из самых разных уголков мира. У них нет врожденных когтей, рогов или иных физических особенностей, что одни считают недостатком, а другие - чистым холстом.$t$,
$t$"Патульяки помешаны на магии, кайцы не могут найти разума, мерманы не способны закрепиться на суше. Мы же, Виртувианцы, во всем своем разнообразии способны на все то, на что неспособны другие."

Виртувианцы - одна из двенадцати признанных рас, появившихся в мире, по легендам, первыми, после их создания под началом богини молнии Крофин. Их продолжительность жизни, которая многими кажется слишком низкой, компенсируется их адаптивностью и их "чистотой". Они смогли расселиться по всему миру, особенно после начала Уманской эры, когда люди захватили большую часть мира. Но это уже было почти полторы тысячелетия назад. Хотя некоторые из людских народов все еще ждут возвращения былого могущества.$t$,
$t$Как и у большинства рас, у почти всех людей весьма напряженные отношения с непризнанными расами.$t$,
'Признанные', 'Гибкость, Адаптивность', 80),

-- ------------------------------------------------------- Природные эльфы
('Природные эльфы', 'Сондорийцы',
$t$Заостренные уши, черные белки глаз, узоры на руках$t$,
$t$Сондорийцы во многом похожи на остальных эльфов в мире, но в отличие от высших эльфов их волосы имеют куда более ограниченный спектр цветов - от пепельного до темно-каштанового. Их кожа не настолько бледная, а глаза могут быть любого натурального цвета, и в отличие от темных эльфов их уши не выглядят длинными и заостренными. Хоть кончик уха все еще слегка острый, сами уши более короткие и широкие. Белки их глаз абсолютно полностью черные, а на руках видны легкие кольчатые узоры. Они как браслеты на руках, идут от запястья до плеча. Количество и расстояние между этими узорами для каждого сондорийца уникально. Когда они колдуют или испытывают сильные эмоции, эти узоры сияют бирюзово-голубым свечением.$t$,
$t$"Природа совершенно отличается от того, к чему привыкли мы. Честно говоря, многие могли бы поучиться ее путям"

Сондорийцы имеют государства и поселения по всему Корису. Некоторые появились давно как государства на юго-западном континенте, некоторые не так давно, как государства на Плато Сал. Появились они, вероятно, с остальными расами. Но скорее всего именно они первыми заселили юго-западный континент, учитывая, что других рас там значительно меньше. Некоторые легенды также указывают на существование на их территориях "глухих зон" - мест, где мир выглядит так же, как он выглядел до Великого пантеона, и откуда не слышно ничего.$t$,
$t$Прямых и длительных конфликтов с другими расами у них нет, зато есть союзники в виде мерманов.$t$,
'Признанные', 'Помощь, Хранение, Восстановление', 175);

-- Вставка с обновлением: если раса с таким названием уже была (из V3), она приводится к настоящим данным
UPDATE race r
SET in_name       = s.in_name,
    short_desc    = s.short_desc,
    appearance    = s.appearance,
    lore          = s.lore,
    relationships = s.relationships,
    status        = s.status,
    archetype     = s.archetype,
    lifespan      = s.lifespan
FROM seed_race s
WHERE r.out_name = s.out_name AND r.is_custom = FALSE;

INSERT INTO race (out_name, in_name, short_desc, appearance, lore, relationships, status, archetype, lifespan)
SELECT s.out_name, s.in_name, s.short_desc, s.appearance, s.lore, s.relationships, s.status, s.archetype, s.lifespan
FROM seed_race s
WHERE NOT EXISTS (
    SELECT 1 FROM race r WHERE r.out_name = s.out_name AND r.is_custom = FALSE
);

-- Удаление временных рас V3, которых нет в настоящих данных.
-- Если на расу что-то ссылается (например, персонаж), она остаётся, а в журнале появляется сообщение.
-- Узлы наследия удаляемой расы удаляются вместе с ней (CASCADE).
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN
        SELECT id, out_name FROM race
        WHERE is_custom = FALSE
          AND out_name NOT IN (SELECT out_name FROM seed_race)
    LOOP
        BEGIN
            DELETE FROM race WHERE id = r.id;
        EXCEPTION WHEN foreign_key_violation OR restrict_violation THEN
            RAISE NOTICE 'Раса "%" оставлена: на нее есть ссылки', r.out_name;
        END;
    END LOOP;
END $$;

-- 2. Древа наследия
CREATE TEMP TABLE seed_node (
    race_out_name  VARCHAR(100) NOT NULL,
    branch_name    VARCHAR(100) NOT NULL,
    name           VARCHAR(100) NOT NULL,
    level_required INT          NOT NULL,
    description    TEXT         NOT NULL,
    prereq_name    VARCHAR(100)
) ON COMMIT DROP;

INSERT INTO seed_node (race_out_name, branch_name, name, level_required, description, prereq_name) VALUES

-- ================================================================ Автоматоны
('Автоматоны', 'Основное наследие', 'Механическое тело', 1,
$t$Вы - конструкт и получаете иммунитет к болезням и ядам.
Вы невосприимчивы к эффектам, восстанавливающим здоровье. Ваше "здоровье" (ХП) восстанавливается только починками навыка Автоматизация (добавляет 8 + модификатор навыка Автоматизация + атрибут Ремесла ХП) и заклинаниями, которые чинят конструкции.
Ваше тело - это ваша броня. Вы не можете носить никакую дополнительную броню. Вместо этого у вас есть базовый DM, равный 2. Этот DM можно увеличить с помощью расовых талантов.
Вы получаете уязвимость к урону кислотой и молнией.
Вы получаете +3 очка, которые можете вложить только в атрибуты Ремесло или Интеллект. Также ваш уровень навыка Автоматизация по умолчанию равен 5.
Правила магической нагрузки неприменимы к вам. Вместо нее у вас есть "Запас Инса". (Расчет максимального запаса и правила использования будут описаны в соответствующем Древе наследия и документе по магии для автоматонов.)
Ваш запас Инса после длительного отдыха снижается на 20% от его максимума, как топливо для работы на следующий день.
Пасть на животе позволяет вам использовать тела погибших органиков как топливо. Вы можете "съесть" тело, получив с его помощью Инс. Получаемый Инс равен (5 + уровень съеденного + ТМН съеденного).$t$, NULL),

('Автоматоны', 'Плата АМЕ', 'Протокол действия: Анализ, выбор: Поглощение, Оставление', 2,
