"Тревожный гул": один раз за короткий отдых вы можете потратить Основное действие, чтобы создать низкочастотный гул, направленный на одну цель в пределах 10 метров. Цель должна совершить спасбросок Ясности ума (DC = 8 + ваш атрибут Выносливости + ваш мод. Скрытности). В случае провала цель чувствует необъяснимую тревогу и панику и получает Малую помеху (-2) на все свои броски атаки и проверки атрибутов на 1 минуту.$t$,
'Анализ звука');

-- Узлы добавляются только тем расам, у которых узлов наследия ещё нет
INSERT INTO heritage_nodes (race_id, branch_name, name, level_required, description, is_custom)
SELECT r.id, n.branch_name, n.name, n.level_required, n.description, FALSE
FROM seed_node n
JOIN race r ON r.out_name = n.race_out_name AND r.is_custom = FALSE
WHERE NOT EXISTS (
    SELECT 1 FROM heritage_nodes h WHERE h.race_id = r.id AND h.is_custom = FALSE
);

-- Условия узлов: узел 5 уровня требует узел 2 уровня своей ветки, 11 уровня - узел 5 уровня
UPDATE heritage_nodes h
SET prerequisite_node_id = p.id
FROM seed_node n
JOIN race r ON r.out_name = n.race_out_name AND r.is_custom = FALSE
JOIN heritage_nodes p ON p.race_id = r.id AND p.name = n.prereq_name AND p.is_custom = FALSE
WHERE n.prereq_name IS NOT NULL
  AND h.race_id = r.id
  AND h.name = n.name
  AND h.is_custom = FALSE;
